import CheckRoundedIcon from '@mui/icons-material/CheckRounded';
import Box from '@mui/material/Box';
import { buttonBaseClasses } from '@mui/material/ButtonBase';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import Radio, { radioClasses, type RadioProps } from '@mui/material/Radio';
import type { SxProps, Theme } from '@mui/material/styles';
import { mergeSlotProps } from '@mui/material/utils';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, type Ref } from 'react';
import { svTokens } from '../../theme/tokens';

export interface SvRadioProps extends Omit<RadioProps, 'ref'> {
  ref?: Ref<HTMLSpanElement> | undefined;
}

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvRadio: SvRadioProps;
  }
  interface Components {
    SvRadio?: { defaultProps?: Partial<SvRadioProps> | undefined } | undefined;
  }
}

const iconSx: SxProps<Theme> = {
  width: 'var(--SvRadio-size)',
  height: 'var(--SvRadio-size)',
  borderRadius: '50%',
  boxSizing: 'border-box',
  flexShrink: 0,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  [`.${radioClasses.root}.${radioClasses.disabled} &`]: { opacity: 0.4 },
  '@media (forced-colors: active)': {
    forcedColorAdjust: 'none',
    [`.${radioClasses.root}.${radioClasses.disabled} &`]: { opacity: 1 },
  },
};

export const SvRadio = forwardRef<HTMLSpanElement, SvRadioProps>(
  function SvRadio(inProps, ref) {
    const muiDefaults = useDefaultProps<SvRadioProps>({
      props: {},
      name: 'MuiRadio',
    });
    const svDefaults = useDefaultProps<SvRadioProps>({
      props: {},
      name: 'SvRadio',
    });
    const svProps = useDefaultProps({ props: inProps, name: 'SvRadio' });
    const resolved = useDefaultProps({ props: svProps, name: 'MuiRadio' });
    const {
      className,
      sx: _sx,
      slotProps,
      icon,
      checkedIcon,
      size = 'small',
      color = 'primary',
      disableRipple = true,
      ...props
    } = resolved;
    const controlSx: SxProps<Theme> = (theme) => {
      const palette = (theme.vars ?? theme).palette;
      const swatch = palette[color as keyof typeof palette];
      const fill =
        swatch && typeof swatch === 'object' && 'main' in swatch
          ? (swatch.main as string)
          : palette.text.secondary;
      return {
        padding: '4px',
        minWidth: 24,
        minHeight: 24,
        '--SvRadio-size': size === 'medium' ? '20px' : '16px',
        '--SvRadio-accent': svTokens(theme).accent,
        '--SvRadio-stroke': svTokens(theme).stroke,
        '--SvRadio-foreground': '#fff',
        '--SvRadio-fill': color === 'primary' ? 'var(--SvRadio-accent)' : fill,
        color: 'var(--SvRadio-stroke)',
        [`&.${radioClasses.disabled}`]: { color: 'var(--SvRadio-stroke)' },
        [`&.${radioClasses.checked}`]: { color: 'var(--SvRadio-fill)' },
        [`&.${buttonBaseClasses.focusVisible}`]: {
          outline: `2px solid ${svTokens(theme).focus}`,
          outlineOffset: 2,
          '@media (forced-colors: active)': { outlineColor: 'Highlight' },
        },
      };
    };
    const rootSx = mergeSx(
      controlSx,
      muiDefaults.sx,
      svDefaults.sx,
      inProps.sx
    );
    return (
      <Radio
        {...props}
        ref={ref as Ref<HTMLButtonElement>}
        size={size}
        color={color}
        disableRipple={disableRipple}
        className={clsx('SvRadio-root', className)}
        sx={rootSx}
        icon={
          icon ?? (
            <Box
              component="span"
              aria-hidden="true"
              className="SvRadio-icon"
              sx={mergeSx(iconSx, {
                border: '2px solid currentColor',
                '@media (forced-colors: active)': {
                  borderColor: 'CanvasText',
                  [`.${radioClasses.root}.${radioClasses.disabled} &`]: {
                    borderColor: 'GrayText',
                  },
                },
              })}
            />
          )
        }
        checkedIcon={
          checkedIcon ?? (
            <Box
              component="span"
              aria-hidden="true"
              className="SvRadio-icon"
              sx={mergeSx(iconSx, {
                backgroundColor: 'currentColor',
                '@media (forced-colors: active)': {
                  backgroundColor: 'Highlight',
                  [`.${radioClasses.root}.${radioClasses.disabled} &`]: {
                    backgroundColor: 'GrayText',
                  },
                },
              })}
            >
              <CheckRoundedIcon
                sx={{
                  fontSize: 'var(--SvRadio-size)',
                  color: 'var(--SvRadio-foreground)',
                  '@media (forced-colors: active)': {
                    color: 'HighlightText',
                    [`.${radioClasses.root}.${radioClasses.disabled} &`]: {
                      color: 'Canvas',
                    },
                  },
                }}
              />
            </Box>
          )
        }
        slotProps={{
          ...slotProps,
          root: mergeSlotProps(slotProps?.root, { sx: rootSx }),
        }}
      />
    );
  }
);
